/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_create(
	struct nb_cb_create_args *args)
{
	if (args->event != NB_EV_VALIDATE)
		return NB_OK;

	afi_t afi;
	safi_t safi;
	const struct lyd_node *bgp_dnode, *cp_dnode;
	const char *vrf_name, *af_name;
	enum bgp_instance_type inst_type;
	bgp_dnode = yang_dnode_get_parent(args->dnode, "bgp");
	cp_dnode = yang_dnode_get_parent(args->dnode, "control-plane-protocol");
	vrf_name = yang_dnode_get_string(cp_dnode, "./vrf");
	af_name = yang_dnode_get_string(args->dnode, "./afi-safi-name");
	if (strmatch(vrf_name, VRF_DEFAULT_NAME)) {
		inst_type = BGP_INSTANCE_TYPE_DEFAULT;
	} else {
		inst_type = BGP_INSTANCE_TYPE_VRF;
	}
	if (yang_dnode_get_bool(bgp_dnode, "./global/instance-type-view")) {
		inst_type = BGP_INSTANCE_TYPE_VIEW;
	}
	yang_afi_safi_identity2value(af_name, &afi, &safi);

	if (afi == AFI_IP || afi == AFI_IP6) {
		if (inst_type != BGP_INSTANCE_TYPE_DEFAULT &&
		    safi != SAFI_UNICAST && safi != SAFI_MULTICAST &&
		    safi != SAFI_EVPN) {
			snprintf(args->errmsg, args->errmsg_len,
				 "Only Unicast/Multicast/EVPN SAFIs supported in non-core instances.");
			return NB_ERR_VALIDATION;
		}
	}

	return NB_OK;
}

