/*
 * XPath: /frr-routing:routing/control-plane-protocols/control-plane-protocol/frr-bgp:bgp/global/afi-safis/afi-safi/ipv6-unicast/vpn-config/import-vpn
 */
int routing_control_plane_protocols_control_plane_protocol_bgp_global_afi_safis_afi_safi_ipv6_unicast_vpn_config_import_vpn_modify(
	struct nb_cb_modify_args *args)
{
	bool is_enable = false;
	enum bgp_instance_type inst_type;
	const char *vrf_name;
	const struct lyd_node *cp_dnode;

	cp_dnode = yang_dnode_get_parent(args->dnode, "control-plane-protocol");

	switch (args->event) {
	case NB_EV_VALIDATE:
		vrf_name = yang_dnode_get_string(cp_dnode, "./vrf");

		if (strmatch(vrf_name, VRF_DEFAULT_NAME))
			inst_type = BGP_INSTANCE_TYPE_DEFAULT;
		else
			inst_type = BGP_INSTANCE_TYPE_VRF;

		if (BGP_INSTANCE_TYPE_VRF != inst_type &&
		    BGP_INSTANCE_TYPE_DEFAULT != inst_type) {
			snprintf(args->errmsg, args->errmsg_len,
				 "import vpn valid only for bgp vrf or default instance");
			return NB_ERR_VALIDATION;
		    }
		break;
	case NB_EV_PREPARE:
	case NB_EV_ABORT:
		break;
	case NB_EV_APPLY:
		if (yang_dnode_get_bool(args->dnode, NULL))
			is_enable = true;
		return bgp_global_afi_safi_ip_unicast_vpn_config_import_export_vpn_modify(
			args, "import", is_enable);
	}

	return NB_OK;
}

